	    break;
	    if (!vim_isIDc(c))
		status = RA_NOMATCH;
	    break;
	    if (VIM_ISDIGIT(*rex.input) || !vim_isIDc(c))
		status = RA_NOMATCH;
	    break;
	    if (!vim_iswordp_buf(rex.input, rex.reg_buf))
		status = RA_NOMATCH;
	    break;
	    if (VIM_ISDIGIT(*rex.input)
				    || !vim_iswordp_buf(rex.input, rex.reg_buf))
		status = RA_NOMATCH;
	    break;
	    if (!vim_isfilec(c))
		status = RA_NOMATCH;
	    break;
	    if (VIM_ISDIGIT(*rex.input) || !vim_isfilec(c))
		status = RA_NOMATCH;
	    break;
	    if (!vim_isprintc(PTR2CHAR(rex.input)))
		status = RA_NOMATCH;
	    break;
	    if (VIM_ISDIGIT(*rex.input) || !vim_isprintc(PTR2CHAR(rex.input)))
		status = RA_NOMATCH;
	    break;
	    if (!VIM_ISWHITE(c))
		status = RA_NOMATCH;
	    break;
	    if (c == NUL || VIM_ISWHITE(c))
		status = RA_NOMATCH;
	    break;
	    if (!ri_digit(c))
		status = RA_NOMATCH;
	    break;
	    if (c == NUL || ri_digit(c))
		status = RA_NOMATCH;
	    break;
	    if (!ri_hex(c))
		status = RA_NOMATCH;
	    break;
	    if (c == NUL || ri_hex(c))
		status = RA_NOMATCH;
	    break;
	    if (!ri_octal(c))
		status = RA_NOMATCH;
	    break;
	    if (c == NUL || ri_octal(c))
		status = RA_NOMATCH;
	    break;
	    if (!ri_word(c))
		status = RA_NOMATCH;
	    break;
	    if (c == NUL || ri_word(c))
		status = RA_NOMATCH;
	    break;
	    if (!ri_head(c))
		status = RA_NOMATCH;
	    break;
	    if (c == NUL || ri_head(c))
		status = RA_NOMATCH;
	    break;
	    if (!ri_alpha(c))
		status = RA_NOMATCH;
	    break;
	    if (c == NUL || ri_alpha(c))
		status = RA_NOMATCH;
	    break;
	    if (!ri_lower(c))
		status = RA_NOMATCH;
	    break;
	    if (c == NUL || ri_lower(c))
		status = RA_NOMATCH;
	    break;
	    if (!ri_upper(c))
		status = RA_NOMATCH;
	    break;
	    if (c == NUL || ri_upper(c))
		status = RA_NOMATCH;
	    break;
	  case EXACTLY:
		int	len;
		char_u	*opnd;
		opnd = OPERAND(scan);
		if (*opnd != *rex.input
			&& (!rex.reg_ic
			    || (!enc_utf8
			      && MB_TOLOWER(*opnd) != MB_TOLOWER(*rex.input))))
