	  case ANYOF:
		char_u  *q = OPERAND(scan);
		if (c == NUL)
		    status = RA_NOMATCH;
		else if ((cstrchr(q, c) == NULL) == (op == ANYOF))
		    status = RA_NOMATCH;
		    int	len = 0;
		    int i;
		    if (enc_utf8)
			len = utfc_ptr2len(q) - utf_ptr2len(q);
		    MB_CPTR_ADV(rex.input);
		    MB_CPTR_ADV(q);
		    for (i = 0; i < len; ++i)
			if (q[i] != rex.input[i])
			    status = RA_NOMATCH;
		    rex.input += len;
		int	i, len;
		char_u	*opnd;
		int	opndc = 0, inpc;
		opnd = OPERAND(scan);
		if ((len = (*mb_ptr2len)(opnd)) < 2)
		    status = RA_NOMATCH;
		if (enc_utf8)
		    opndc = utf_ptr2char(opnd);
		if (enc_utf8 && utf_iscomposing(opndc))
		    status = RA_NOMATCH;
		    for (i = 0; rex.input[i] != NUL;
						i += utf_ptr2len(rex.input + i))
