	if (tagp.is_etag && *str == ',')// stop at ',' after line number
	    break;
#endif
	*pbuf_end++ = *str++;
	if (pbuf_end - pbuf + 1 + isdigit >= LSIZE)
	    break;
    }
    *pbuf_end = NUL;

