static pos_T *
off2pos(buf_T *buf, long offset)
{
    linenr_T	 lnum;
    static pos_T pos;

    pos.lnum = 0;
    pos.col = 0;
    pos.coladd = 0;

    if (!(buf->b_ml.ml_flags & ML_EMPTY))
    {
	if ((lnum = ml_find_line_or_offset(buf, (linenr_T)0, &offset)) < 0)
	    return NULL;
	pos.lnum = lnum;
	pos.col = offset;
    }

    return &pos;
}

// Function: pos2off from current file (lines 3389-3402)
static long
pos2off(buf_T *buf, pos_T *pos)
{
    long	 offset = 0;

    if (buf->b_ml.ml_flags & ML_EMPTY)
	return 0;

    if ((offset = ml_find_line_or_offset(buf, pos->lnum, 0)) < 0)
	return 0;
    offset += pos->col;

    return offset;
}

