int
hash_add_item(
    hashtab_T	*ht,
    hashitem_T	*hi,
    char_u	*key,
    hash_T	hash)
{
    // If resizing failed before and it fails again we can't add an item.
    if (ht->ht_flags & HTFLAGS_ERROR)
	return FAIL;

    ++ht->ht_used;
    ++ht->ht_changed;
