		++idx;
#endif
		if (menu->priority <= pri_tab[pri_idx])
		{
		    lower_pri = menup;
#ifdef FEAT_GUI
		    new_idx = idx;
#endif
		}
	    }
	    menu = menu->next;
	}
	if (menu == NULL)
	{
	    menu = ALLOC_CLEAR_ONE(vimmenu_T);
	    if (menu == NULL)
