		    oldp = ml_get(lnum);
		    oldlen = ml_get_len(lnum);
		    if (lnum > start_lnum)
		    {
			pos_T   pos;

			pos.lnum = lnum;
			if (getvpos(&pos, vcol) == OK)
			    col = pos.col;
			else
