	    *error = FCERR_SCRIPT;
	else
	{
	    fname_buflen += vim_snprintf((char *)fname_buf + 3,
						FLEN_FIXED - 3,
	}
    }
    fnamelen = fname_buflen + STRLEN(script_name);
    if (fnamelen < FLEN_FIXED)
    {
	STRCPY(fname_buf + fname_buflen, script_name);  // The line where the warning is located
	fname = fname_buf;
