  static void
xxdline(FILE *fp, char *l, int nz)
{
  static char z[LLEN+1];
  static signed char zero_seen = 0;
  if (!nz && zero_seen == 1)
    strcpy(z, l);  // The line where the warning is located
  if (nz || !zero_seen++)
    {
      if (nz)
	{
	  if (zero_seen == 2)
	    fputs_or_die(z, fp);
	  if (zero_seen > 2)
	    fputs_or_die("*\n", fp);
	}
      if (nz >= 0 || zero_seen > 0)
	fputs_or_die(l, fp);
    }
}


