// Function: get_indent_str from src/indent.c (lines 452-475)
int
get_indent_str(
    char_u	*ptr,
    int		ts,
    int		no_ts) // if TRUE, count a tab as ^I
{
    int		count = 0;

    for ( ; *ptr; ++ptr)
    {
	if (*ptr == TAB)    // count a tab for what it is worth
	{
	    if (!no_ts)
		count += ts - (count % ts);
	    else
		count += ptr2cells(ptr);
	}
	else if (*ptr == ' ')
	    ++count;		// count a space for one
	else
	    break;
    }
    return count;
}

