		semsg(_(e_setting_v_str_to_value_with_wrong_type), varname);
	}
	clear_tv(&di->di_tv);
	if ((flags & ASSIGN_UPDATE_BLOCK_ID)
				       && SCRIPT_ID_VALID(current_sctx.sc_sid))
	{
	    scriptitem_T *si = SCRIPT_ITEM(current_sctx.sc_sid);
