		if (ptr)
		    search_ctx->ffsc_stopdirs_v = ptr;
		walker = vim_strchr(walker, ';');
		len = walker ? (size_t)(walker - helper) : STRLEN(helper);
		if (*helper != NUL && !vim_isAbsName(helper)
