		{
		    vim_strncpy(ff_expand_buffer, helper, len);
		    search_ctx->ffsc_stopdirs_v[dircount-1] =
					FullName_save(ff_expand_buffer, FALSE);
		}
		else
		    search_ctx->ffsc_stopdirs_v[dircount-1] =
						     vim_strnsave(helper, len);
		if (walker)
		    walker++;
		dircount++;
	    } while (walker != NULL);
	    search_ctx->ffsc_stopdirs_v[dircount-1] = NULL;
	}
    }
