		if (tearpath != NULL)
		{
		    char_u  *s;
		    int	    idx;
		    STRCPY(tearpath, menu_path);
		    idx = (int)(next_name - path_name - 1);
		    for (s = tearpath; *s && s < tearpath + idx; MB_PTR_ADV(s))
		    {
