			*msgp++ = (dfltbutton == 1) ? '[' : '(';
			msgp += copy_char(r, msgp, FALSE);
			*msgp++ = (dfltbutton == 1) ? ']' : ')';
			hotkp[copy_char(r, hotkp, TRUE)] = NUL;
		    ++len;	    // '&a' -> '[a]'
		    msgp += copy_char(r, msgp, FALSE);
	    }
	    MB_PTR_ADV(r);
	}
	if (copy)
	{
	    *msgp++ = ':';
	    *msgp++ = ' ';
	    *msgp = NUL;
