#define HASHITEM_EMPTY(hi) ((hi)->hi_key == NULL || (hi)->hi_key == &hash_removed)

// Macro: HI2AH from current file (line 1841)
#define HI2AH(hi)   ((affheader_T *)(hi)->hi_key)

